#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("oceny.txt");
    int cnt[7] = {};
    int x;
    while (plik >> x) cnt[x]++;

    cout << "a) Histogram ocen:" << endl;
    for (int i = 1; i <= 6; i++) {
        cout << "   " << i << " | ";
        for (int j = 0; j < cnt[i]; j++) cout << "*";
        cout << endl;
    }

    int maxOcena = 1, maxCnt = cnt[1];
    for (int i = 2; i <= 6; i++) {
        if (cnt[i] > maxCnt) {
            maxCnt = cnt[i];
            maxOcena = i;
        }
    }
    cout << endl << "b) Najczestsza ocena: " << maxOcena << " (" << maxCnt << " razy)" << endl;
    return 0;
}
```

Weryfikacja:
- cnt[1]=0, cnt[2]=1, cnt[3]=4, cnt[4]=5, cnt[5]=4, cnt[6]=1
- Suma: 0+1+4+5+4+1 = 15 (OK)
- Gwiazdki: 2->*, 3->****, 4->*****, 5->****, 6->*
- Max: cnt[4]=5, wiec najczestsza ocena = 4 (5 razy)
